    fetchTools();
    fetchServices();
    fetchToolUsage();
  }, []);

  const fetchToolUsage = async () => {
    try {
        const stats = await apiClient.getToolUsage();
      if (!stats || !Array.isArray(stats)) return;
        const statsMap: Record<string, ToolAnalytics> = {};
        stats.forEach(s => {
            statsMap[`${s.name}@${s.serviceId}`] = s;
        });
        setToolUsage(statsMap);
    } catch (e) {
        console.error("Failed to fetch tool usage", e);
    }
  };

  const fetchTools = async () => {
    try {
      const res = await apiClient.listTools();
      if (!res) {
        setTools([]);
        return;
      }
      if (Array.isArray(res)) {
        setTools(res);
      } else if (res && Array.isArray(res.tools)) {
        setTools(res.tools);
      } else {
        setTools([]);
      }
    } catch (e) {
      console.error("Failed to fetch tools", e);
      setTools([]);
    }
  };

  const fetchServices = async () => {
    try {
      const res = await apiClient.listServices();
      if (!res) {
        setServices([]);
        return;
      }
      if (Array.isArray(res)) {
        setServices(res);
      } else if (res && Array.isArray(res.services)) {
        setServices(res.services);
      } else {
        setServices([]);
      }
    } catch (e) {
      console.error("Failed to fetch services", e);
      setServices([]);
    }
  };

  const toggleTool = async (name: string, currentStatus: boolean) => {
    // Optimistic update
    setTools(tools.map(t => t.name === name ? { ...t, disable: currentStatus } : t));

    try {
        await apiClient.setToolStatus(name, !currentStatus);
    } catch (e) {
        console.error("Failed to toggle tool", e);
        fetchTools(); // Revert
    }
  };

  const handleBulkToggle = async (names: string[], enabled: boolean) => {
    // Optimistic update
    setTools(tools.map(t => names.includes(t.name) ? { ...t, disable: !enabled } : t));

    try {
        await Promise.all(names.map(name => apiClient.setToolStatus(name, !enabled)));
        toast({
            title: enabled ? "Tools Enabled" : "Tools Disabled",
            description: `${names.length} tools have been ${enabled ? "enabled" : "disabled"}.`
        });
    } catch (e) {
        console.error("Failed to bulk toggle tools", e);
        fetchTools(); // Revert
        toast({
            variant: "destructive",
            title: "Error",
            description: "Failed to update some tools."
        });
    }
  };

  const handleBulkPin = (names: string[], pinned: boolean) => {
      if (pinned) {
          bulkPin(names);
      } else {
          bulkUnpin(names);
      }
      toast({
            title: pinned ? "Tools Pinned" : "Tools Unpinned",
            description: `${names.length} tools have been ${pinned ? "pinned" : "unpinned"}.`
      });
  };

  const toggleCompact = () => {
    const newState = !isCompact;
    setIsCompact(newState);
    localStorage.setItem("tools_compact_view", String(newState));
  };

  const openInspector = (tool: ToolDefinition) => {
      setSelectedTool(tool);
      setInspectorOpen(true);
  };

  const filteredTools = tools
    .filter((t) => !showPinnedOnly || isPinned(t.name))
    .filter((t) => selectedService === "all" || t.serviceId === selectedService)
    .filter((t) =>
      searchQuery === "" ||
      t.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.description.toLowerCase().includes(searchQuery.toLowerCase())
    )
    .sort((a, b) => {
      const aPinned = isPinned(a.name);
      const bPinned = isPinned(b.name);
      if (aPinned && !bPinned) return -1;
      if (!aPinned && bPinned) return 1;
      return a.name.localeCompare(b.name);
    });

  // Grouping logic
  const groupedTools = filteredTools.reduce((acc, tool) => {
    let key = "Other";
    if (groupBy === "service") {
      const service = services.find((s) => s.id === tool.serviceId);
      key = service ? service.name : tool.serviceId || "Unknown Service";
    } else if (groupBy === "category") {
      key = tool.tags && tool.tags.length > 0 ? tool.tags[0] : "Uncategorized";
    }

    if (!acc[key]) {
      acc[key] = [];
    }
    acc[key].push(tool);
    return acc;
  }, {} as Record<string, ToolDefinition[]>);


  if (!isLoaded) {
      return (
          <div className="flex-1 p-8 animate-pulse text-muted-foreground">
              Loading tools...
          </div>
      );
  }

  return (
    <div className="flex-1 space-y-4 p-8 pt-6">
      <div className="flex items-center justify-between">
        <h2 className="text-3xl font-bold tracking-tight">Tools</h2>
        <div className="flex items-center space-x-4">
            <SmartToolSearch
                tools={tools}
                searchQuery={searchQuery}
                setSearchQuery={setSearchQuery}
                onToolSelect={openInspector}
            />
            <div className="flex items-center space-x-2">
                <Select value={groupBy} onValueChange={(v: any) => setGroupBy(v)}>
                    <SelectTrigger className="w-[180px] backdrop-blur-sm bg-background/50">
                        <Layers className="mr-2 h-4 w-4" />
                        <SelectValue placeholder="Group By" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="none">No Grouping</SelectItem>
                        <SelectItem value="service">Group by Service</SelectItem>
                        <SelectItem value="category">Group by Category</SelectItem>
                    </SelectContent>
                </Select>
            </div>
            <div className="flex items-center space-x-2">
                <Select value={selectedService} onValueChange={setSelectedService}>
                    <SelectTrigger className="w-[200px] backdrop-blur-sm bg-background/50">
                        <SelectValue placeholder="Filter by Service" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Services</SelectItem>
                        {services.map((service) => (
                            <SelectItem key={service.id} value={service.id}>
                                {service.name}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
            </div>
            <div className="flex items-center space-x-2">
                <Switch
                    id="show-pinned"
                    checked={showPinnedOnly}
                    onCheckedChange={setShowPinnedOnly}
                />
                <label htmlFor="show-pinned" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
                    Show Pinned Only
                </label>
            </div>
            <Button
                variant="ghost"
                size="icon"
                onClick={toggleCompact}
                title={isCompact ? "Comfortable View" : "Compact View"}
                className="h-9 w-9"
            >
                {isCompact ? <LayoutList className="h-4 w-4" /> : <List className="h-4 w-4" />}
            </Button>
        </div>
      </div>

      <Card className="backdrop-blur-sm bg-background/50">
        <CardHeader>
          <CardTitle>Available Tools</CardTitle>
          <CardDescription>Manage exposed tools from connected services.</CardDescription>
        </CardHeader>
        <CardContent>
          {groupBy === "none" ? (
            <ToolTable
              tools={filteredTools}
              isCompact={isCompact}
              isPinned={isPinned}
              togglePin={togglePin}
              toggleTool={toggleTool}
              openInspector={openInspector}
              usageStats={toolUsage}
              onBulkToggle={handleBulkToggle}
              onBulkPin={handleBulkPin}
            />
          ) : (
            <Accordion type="multiple" defaultValue={Object.keys(groupedTools)} className="w-full">
              {Object.entries(groupedTools).map(([groupName, groupTools]) => (
                <AccordionItem key={groupName} value={groupName}>
                  <AccordionTrigger className="hover:no-underline px-2">
                    <span className="font-medium text-lg flex items-center">
                      {groupName}
                      <Badge variant="secondary" className="ml-2 text-xs">
                        {groupTools.length}
                      </Badge>
                    </span>
                  </AccordionTrigger>
                  <AccordionContent>
                    <ToolTable
                      tools={groupTools}
                      isCompact={isCompact}
                      isPinned={isPinned}
                      togglePin={togglePin}
                      toggleTool={toggleTool}
                      openInspector={openInspector}
                      usageStats={toolUsage}
                      onBulkToggle={handleBulkToggle}
                      onBulkPin={handleBulkPin}
                    />
                  </AccordionContent>
                </AccordionItem>
              ))}
            </Accordion>
          )}
        </CardContent>
      </Card>

      <ToolInspector
        tool={selectedTool}
        open={inspectorOpen}
        onOpenChange={setInspectorOpen}
      />
    </div>
  );
}

