"use client";

import React, { useMemo, useEffect } from "react";
import {
    ReactFlow,
    Controls,
    Background,
    BackgroundVariant,
    useNodesState,
    useEdgesState,
    Position,
    Node,
    Edge,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import jsyaml from "js-yaml";
import dagre from "dagre";
import {
    Database,
    Terminal,
    Cpu,
    Box,
    AlertTriangle
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

interface StackGraphProps {
    yamlContent: string;
}

interface ParsedService {
    name: string;
    image?: string;
    command?: string;
    envCount: number;
    ports: string[];
    type: "image" | "command" | "unknown";
    dependsOn?: string[];
}

const nodeWidth = 250;
const nodeHeight = 100;

const getLayoutedElements = (nodes: Node[], edges: Edge[]) => {
    const dagreGraph = new dagre.graphlib.Graph();
    dagreGraph.setDefaultEdgeLabel(() => ({}));

    dagreGraph.setGraph({ rankdir: 'TB' });

    nodes.forEach((node) => {
        dagreGraph.setNode(node.id, { width: nodeWidth, height: nodeHeight });
    });

    edges.forEach((edge) => {
        dagreGraph.setEdge(edge.source, edge.target);
    });

    dagre.layout(dagreGraph);

    const layoutedNodes = nodes.map((node) => {
        const nodeWithPosition = dagreGraph.node(node.id);
        node.position = {
            x: nodeWithPosition.x - nodeWidth / 2,
            y: nodeWithPosition.y - nodeHeight / 2,
        };
        return node;
    });

    return { nodes: layoutedNodes, edges };
};

/**
 * ServiceNode component for ReactFlow.
 */
const ServiceNode = React.memo(({ data }: { data: ParsedService }) => {
    let Icon = Cpu;
    if (data.type === "image") Icon = Database;
    if (data.type === "command") Icon = Terminal;

    return (
        <Card className="w-[240px] shadow-md border-l-4 border-l-primary/50 text-xs">
            <CardHeader className="p-2 pb-1 bg-muted/20">
