                      </TooltipTrigger>
                      <TooltipContent className="max-w-[300px] text-xs">
                        <p>{schema.description}</p>
                      </TooltipContent>
                    </Tooltip>
               )}
          </div>
        )}
      </div>
    </div>
  );
}

