                                            ) : user.authentication?.basicAuth || (user.authentication as any)?.basic_auth ? (
                                                <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-muted/50 border">
                                                    <Lock className="h-3.5 w-3.5 text-blue-500" />
